<script lang="ts">
 import {X} from 'lucide-svelte';
 import {canPreviewAttachment,addressFull,mailDate,type MailMessage,type MailAttachment} from './mail';
 import {renderMailHtml} from './mail-html';
 import {safeMessageLink} from './message-body';
 import {fileSize} from './attachments';
 let {thread,bodies,files,hashes,focused,busy,saving,errors,more,notice,onCollect,onMore,onMessage,onPreview,onSave,onClose,onLink}:{thread:MailMessage[];bodies:Record<string,MailMessage>;files:Record<string,MailAttachment[]>;hashes:Record<string,string>;focused:string;busy:boolean;saving:boolean;errors:Record<string,string>;more:Record<string,string|null>;notice:string;onCollect:()=>void;onMore:(id:string)=>void;onMessage:(id:string)=>void;onPreview:(id:string,f:MailAttachment)=>void;onSave:(id:string,f:MailAttachment)=>void;onClose:()=>void;onLink:(url:string)=>void}=$props();
 let scope=$state('all'),tab=$state('files'),inline=$state(false),link=$state('');
 const messages=$derived(scope==='selected'?thread.filter(m=>m.id===focused):thread);
 const participants=$derived.by(()=>{const found=new Map<string,string>();for(const m of thread){const full=bodies[m.id]??m;for(const a of [full.from,...full.toRecipients??[],...full.ccRecipients??[]]){const email=a?.emailAddress?.address;if(email)found.set(email.toLowerCase(),addressFull(a));}}return [...found.values()];});
 const entries=$derived.by(()=>{const groups=new Map<string,{file:MailAttachment; sources:{id:string;file:MailAttachment}[]}>();for(const m of messages)for(const f of files[m.id]??[]){const image=f.contentType?.toLowerCase().startsWith('image/');if(tab==='files'&&(image||f.isInline)||tab==='images'&&(!image||f.isInline&&!inline))continue;const hash=image?hashes[JSON.stringify([m.id,f.id])]:undefined;const key=hash?`hash:${hash}`:JSON.stringify([m.id,f.id]);const existing=groups.get(key);if(existing)existing.sources.push({id:m.id,file:f});else groups.set(key,{file:f,sources:[{id:m.id,file:f}]});}return [...groups.values()];});
 const links=$derived.by(()=>{const found=new Map<string,string[]>();for(const m of messages){const b=bodies[m.id];if(!b)continue;const urls=b.body?.contentType?.toLowerCase()==='html'?renderMailHtml(b.body.content??'').links:(b.body?.content??'').match(/https?:\/\/[^\s<>"']+/g)??[];for(const raw of urls){const url=safeMessageLink(raw);if(url){const ids=found.get(url)??[];if(!ids.includes(m.id))ids.push(m.id);found.set(url,ids);}}}return [...found].map(([url,ids])=>({url,ids}));});
 const collected=$derived(thread.filter(m=>bodies[m.id]&&files[m.id]&&!more[m.id]).length);
</script>
<aside class="mail-details" aria-label="Mail conversation details">
 <header><div><span class="eyebrow">CONVERSATION DETAILS</span><h3>People & shared media</h3></div><button aria-label="Close mail details" onclick={onClose}><X size={18}/></button></header>
 <div class="details-scroll"><p>{thread.length} loaded emails · {collected} fully indexed</p>{#if thread.length}<p>{mailDate(thread[0])}<br>to {mailDate(thread[thread.length-1])}</p>{/if}
 <details><summary>Participants ({participants.length})</summary>{#each participants as person}<p>{person}</p>{/each}<small>From loaded sender, To and Cc fields.</small></details>
 <div class="scope" role="group" aria-label="Shared mail media scope"><button aria-pressed={scope==='all'} onclick={()=>scope='all'}>Entire conversation</button><button aria-pressed={scope==='selected'} disabled={!focused} onclick={()=>scope='selected'}>Selected email</button></div>
 {#if scope==='selected'}{@const message=thread.find(m=>m.id===focused)}<p class="scope-note">Selected email · {addressFull(message?.from)} · {message?mailDate(message):''}</p>{/if}
 <nav aria-label="Shared mail media type">{#each ['files','images','links'] as value}<button aria-pressed={tab===value} onclick={()=>tab=value}>{value[0].toUpperCase()+value.slice(1)}</button>{/each}</nav>
 {#if tab==='images'}<label><input type="checkbox" bind:checked={inline}/> Include inline images</label><p>Inline images may include signatures or pasted screenshots. Matching images are grouped after preview confirms identical bytes.</p>{/if}
 <button class="collect" disabled={busy} onclick={onCollect}>{busy?'Collecting media…':'Collect more conversation media'}</button><p>Indexes up to 25 loaded emails per pass. Files download only when you preview or save. Load older conversation history in the reader to include it.</p>
 {#each messages as m}{#if errors[m.id]}<p role="alert">{errors[m.id]}<button disabled={busy} onclick={onCollect}>Retry collection</button></p>{/if}{#if more[m.id]}<button disabled={busy} onclick={()=>onMore(m.id)}>More attachments · {mailDate(m)}</button>{/if}{/each}
 {#if tab==='links'}
 {#each links as item}<section><button class="item" onclick={()=>link=item.url}>{item.url}</button>{#each item.ids as id}<button class="source" onclick={()=>onMessage(id)}>View source email · {mailDate(thread.find(m=>m.id===id)!)}</button>{/each}</section>{:else}<p>No links in indexed emails for this scope.</p>{/each}
 {#if link}<div class="link-review"><p>Open this destination in your browser?</p><p>{link}</p><button onclick={()=>{onLink(link);link='';}}>Open link</button><button onclick={()=>link=''}>Cancel</button></div>{/if}
 {:else}
 {#each entries as entry}<section><strong>{entry.file.name||'Attachment'}</strong><p>{fileSize(entry.file.size??0)}{entry.file.isInline?' · Inline image':''}{entry.sources.length>1?` · ${entry.sources.length} identical copies`:''}</p><div class="actions">{#if canPreviewAttachment(entry.file)}<button disabled={saving} onclick={()=>onPreview(entry.sources[0].id,entry.file)}>Preview</button>{/if}<button disabled={saving} onclick={()=>onSave(entry.sources[0].id,entry.file)}>Save</button></div><details><summary>{entry.sources.length===1?'Source email':`Appears in ${entry.sources.length} emails`}</summary>{#each entry.sources as source}<button class="source" onclick={()=>onMessage(source.id)}>{addressFull(thread.find(m=>m.id===source.id)?.from)} · {mailDate(thread.find(m=>m.id===source.id)!)}</button>{/each}</details></section>{:else}<p>No {tab} in indexed emails for this scope{tab==='images'&&!inline?' (inline images hidden)':''}.</p>{/each}
 {/if}
 {#if notice}<p role="status">{notice}</p>{/if}
 </div>
</aside>
<style>
.mail-details{width:320px;max-width:40%;flex:none;display:flex;flex-direction:column;min-height:0;border-left:1px solid var(--border);background:var(--surface-panel);color:var(--text-primary)}header{padding:24px 20px;display:flex;align-items:center;gap:12px;justify-content:space-between;border-bottom:1px solid var(--border)}h3{font-size:17px;margin:10px 0 0}.details-scroll{overflow:auto;padding:16px 20px;overflow-wrap:anywhere}p,small,label,summary{font-size:11px;line-height:1.7;color:var(--text-secondary)}button{font-size:11px;color:var(--accent);padding:7px 9px;border:1px solid var(--border);border-radius:6px}button:disabled{opacity:.45}.scope,nav,.actions{display:flex;gap:6px;flex-wrap:wrap;margin:14px 0}button[aria-pressed=true]{background:var(--accent-soft);border-color:var(--accent);color:var(--accent)}section{border-bottom:1px solid var(--border);padding:16px 0}strong{font-size:12px}.source,.item{text-align:left;display:block;width:100%;margin:6px 0;overflow-wrap:anywhere}.source{font-size:10px}summary{cursor:pointer;color:var(--accent)}.scope-note{border-left:3px solid var(--accent);padding-left:10px}.collect{margin-top:14px}.link-review{border:1px solid var(--accent);padding:10px;border-radius:8px}@media(max-width:850px){.mail-details{position:absolute;right:0;top:0;bottom:0;width:340px;max-width:90%;z-index:5;box-shadow:-12px 0 28px #0004}}
</style>
